import assert from "node:assert/strict";
import { test } from "node:test";

import { User } from "../../shop/users.js";
import { makeShop } from "../helpers.js";

test("checkout without a saved address throws CheckoutError", () => {
  const { cart, orders } = makeShop();
  const newbie = new User({ id: "u_new", email: "new@example.com", name: "New Customer" });
  cart.add("MUG-01");
  assert.throws(() => orders.checkout(cart, newbie), { name: "CheckoutError", message: /address/ });
});

test("explicit address still works for a new customer", () => {
  const { cart, orders, home } = makeShop();
  const newbie = new User({ id: "u_new", email: "new@example.com", name: "New Customer" });
  cart.add("MUG-01");
  assert.equal(orders.checkout(cart, newbie, { shippingAddress: home }).address, home);
});

